CREATE TABLE "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE session (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE INDEX session_user_idx ON session("userId");
CREATE TABLE account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE("providerId", "accountId"));
CREATE INDEX account_user_idx ON account("userId");
CREATE TABLE verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier_idx ON verification(identifier);
CREATE TABLE "rateLimit" (id text PRIMARY KEY, key text NOT NULL UNIQUE, count integer NOT NULL, "lastRequest" bigint NOT NULL);
CREATE TABLE portfolios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(80) NOT NULL, cash numeric(20,4) NOT NULL CHECK(cash >= 0), risk_limit numeric(6,4) NOT NULL DEFAULT 0.05 CHECK(risk_limit BETWEEN 0.005 AND 0.5), is_demo boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members (portfolio_id uuid NOT NULL REFERENCES portfolios(id), user_id text NOT NULL REFERENCES "user"(id), role text NOT NULL CHECK(role IN ('owner','manager','viewer')), PRIMARY KEY(portfolio_id,user_id));
CREATE INDEX members_user_idx ON members(user_id,portfolio_id);
CREATE TABLE holdings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), portfolio_id uuid NOT NULL REFERENCES portfolios(id), symbol varchar(12) NOT NULL CHECK(symbol ~ '^[A-Z][A-Z0-9.-]{0,11}$'), quantity numeric(20,6) NOT NULL CHECK(quantity >= 0), cost numeric(16,4) NOT NULL CHECK(cost > 0), price numeric(16,4) NOT NULL CHECK(price > 0), volatility numeric(8,6) NOT NULL CHECK(volatility BETWEEN 0.0001 AND 1), marked_at timestamptz NOT NULL DEFAULT now(), UNIQUE(portfolio_id,symbol));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), portfolio_id uuid NOT NULL REFERENCES portfolios(id), holding_id uuid NOT NULL REFERENCES holdings(id), actor_id text NOT NULL REFERENCES "user"(id), quantity numeric(20,6) NOT NULL CHECK(quantity > 0), price numeric(16,4) NOT NULL CHECK(price > 0), proceeds numeric(20,4) NOT NULL CHECK(proceeds > 0), idempotency_key uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(portfolio_id,idempotency_key));
CREATE INDEX orders_portfolio_date_idx ON orders(portfolio_id,created_at DESC,id);
CREATE TABLE audit_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, portfolio_id uuid NOT NULL REFERENCES portfolios(id), actor_id text NOT NULL REFERENCES "user"(id), action text NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_portfolio_date_idx ON audit_events(portfolio_id,created_at DESC,id);
CREATE FUNCTION prevent_audit_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit events are append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_audit_mutation();
CREATE TABLE request_limits (key text NOT NULL, bucket bigint NOT NULL, count integer NOT NULL DEFAULT 1, PRIMARY KEY(key,bucket));
